double pans = ouf.readDouble(), jans = ans.readDouble();
if (isnan(pans)) quitf(_wa, "nan output");
if (abs(pans - jans) < 1e-3)
  quitf(_ok, "Good job");
else
  quitf(_wa, "expected %f found %f", jans, pans);

